  "fictional": true,
  "scope": "Complete supplied six-repository fixture; no live account or network inspection",
  "census": {"date":"2026-10-28","repositories":6,"listing_pages":[4,2,0],"depth":"All listed fixture files supplied; no other code or downstream consumers supplied"},
  "repositories": [
